pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "", ""); }
    function testRegression_property() public {
        uint256 value = 10;
        bool success;
        try c.burn(value) { success = true; }
        catch { success = false; }
        assertTrue(success);
    }
}
